const j = $json;
const workflowName = j.workflow?.name || 'unknown workflow';
const nodeName = j.execution?.lastNodeExecuted || j.trigger?.node || 'unknown node';
const message = j.execution?.error?.message || j.execution?.error?.description || 'no error message captured';
const execUrl = j.execution?.url || (j.workflow?.id ? `(execution url unavailable -- check workflow ${j.workflow.id} in n8n)` : 'unavailable');

return [{ json: {
  text: `Post-Event Engine FAILED\nWorkflow: ${workflowName}\nNode: ${nodeName}\nError: ${message}\nExecution: ${execUrl}`
} }];
